    private void btnConsultarActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnConsultarActionPerformed
        
String codigoTexto = txtCodigo.getText().trim();

if (codigoTexto.isEmpty()) {
    javax.swing.JOptionPane.showMessageDialog(
            this, "Ingresa el código del paquete.");
    return;
}

try {
    int codigo = Integer.parseInt(codigoTexto);

    UMG.DAO.PaqueteDAO dao = new UMG.DAO.PaqueteDAO();
    UMG.modelo.Paquete paquete = dao.buscar(codigo);

    if (paquete != null) {
        txtDescripcion.setText(paquete.getDescripcion());
        txtDestinatario.setText(paquete.getDestinatario());
        txtDireccion.setText(paquete.getDireccionDestinatario());
        txtDniCamionero.setText(paquete.getDniCamionero());

        javax.swing.JOptionPane.showMessageDialog(
                this, "Paquete encontrado correctamente.");
    } else {
        javax.swing.JOptionPane.showMessageDialog(
                this, "No se encontró un paquete con ese código.");
    }

} catch (NumberFormatException e) {
    javax.swing.JOptionPane.showMessageDialog(
            this, "El código debe ser un número entero.");
} catch (java.sql.SQLException e) {
    javax.swing.JOptionPane.showMessageDialog(
            this, "Error al consultar: " + e.getMessage());
}

    }//GEN-LAST:event_btnConsultarActionPerformed

    private void btnGuardarActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnGuardarActionPerformed
        
String descripcion = txtDescripcion.getText().trim();
String destinatario = txtDestinatario.getText().trim();
String direccion = txtDireccion.getText().trim();
String dniCamionero = txtDniCamionero.getText().trim();

if (descripcion.isEmpty() || destinatario.isEmpty()
        || direccion.isEmpty() || dniCamionero.isEmpty()) {
    javax.swing.JOptionPane.showMessageDialog(
            this, "Completa todos los campos.");
    return;
}

try {
    UMG.modelo.Paquete paquete = new UMG.modelo.Paquete(
            0, descripcion, destinatario, direccion, dniCamionero);

    UMG.DAO.PaqueteDAO dao = new UMG.DAO.PaqueteDAO();

    if (dao.insertar(paquete)) {
        javax.swing.JOptionPane.showMessageDialog(
                this, "Paquete guardado correctamente.");
        txtCodigo.setText("");
        txtDescripcion.setText("");
        txtDestinatario.setText("");
        txtDireccion.setText("");
        txtDniCamionero.setText("");
    } else {
        javax.swing.JOptionPane.showMessageDialog(
                this, "No se pudo guardar el paquete.");
    }

} catch (java.sql.SQLException e) {
    javax.swing.JOptionPane.showMessageDialog(
            this, "Error al guardar: " + e.getMessage());
}

    }//GEN-LAST:event_btnGuardarActionPerformed

    private void btnActualizarActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnActualizarActionPerformed
        
String codigoTexto = txtCodigo.getText().trim();
String descripcion = txtDescripcion.getText().trim();
String destinatario = txtDestinatario.getText().trim();
String direccion = txtDireccion.getText().trim();
String dniCamionero = txtDniCamionero.getText().trim();

if (codigoTexto.isEmpty() || descripcion.isEmpty()
        || destinatario.isEmpty() || direccion.isEmpty()
        || dniCamionero.isEmpty()) {
    javax.swing.JOptionPane.showMessageDialog(
            this, "Completa todos los campos.");
    return;
}

try {
    int codigo = Integer.parseInt(codigoTexto);

    UMG.modelo.Paquete paquete = new UMG.modelo.Paquete(
            codigo, descripcion, destinatario, direccion, dniCamionero);

    UMG.DAO.PaqueteDAO dao = new UMG.DAO.PaqueteDAO();

    if (dao.actualizar(paquete)) {
        javax.swing.JOptionPane.showMessageDialog(
                this, "Paquete actualizado correctamente.");
    } else {
        javax.swing.JOptionPane.showMessageDialog(
                this, "No se encontró el paquete para actualizar.");
    }

} catch (NumberFormatException e) {
    javax.swing.JOptionPane.showMessageDialog(
            this, "El código debe ser un número entero.");
} catch (java.sql.SQLException e) {
    javax.swing.JOptionPane.showMessageDialog(
            this, "Error al actualizar: " + e.getMessage());
}

    }//GEN-LAST:event_btnActualizarActionPerformed

    private void btnEliminarActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnEliminarActionPerformed
        
String codigoTexto = txtCodigo.getText().trim();

if (codigoTexto.isEmpty()) {
    javax.swing.JOptionPane.showMessageDialog(
            this, "Ingresa el código del paquete que deseas eliminar.");
    return;
}

int confirmar = javax.swing.JOptionPane.showConfirmDialog(
        this,
        "¿Estás seguro de eliminar el paquete con código " + codigoTexto + "?",
        "Confirmar eliminación",
        javax.swing.JOptionPane.YES_NO_OPTION);

if (confirmar != javax.swing.JOptionPane.YES_OPTION) {
    return;
}

try {
    int codigo = Integer.parseInt(codigoTexto);

    UMG.DAO.PaqueteDAO dao = new UMG.DAO.PaqueteDAO();

    if (dao.eliminar(codigo)) {
        javax.swing.JOptionPane.showMessageDialog(
                this, "Paquete eliminado correctamente.");

        txtCodigo.setText("");
        txtDescripcion.setText("");
        txtDestinatario.setText("");
        txtDireccion.setText("");
        txtDniCamionero.setText("");
    } else {
        javax.swing.JOptionPane.showMessageDialog(
                this, "No se encontró el paquete para eliminar.");
    }

} catch (NumberFormatException e) {
    javax.swing.JOptionPane.showMessageDialog(
            this, "El código debe ser un número entero.");
} catch (java.sql.SQLException e) {
    javax.swing.JOptionPane.showMessageDialog(
            this, "Error al eliminar: " + e.getMessage());
}

    }//GEN-LAST:event_btnEliminarActionPerformed

    private void btnLimpiarActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnLimpiarActionPerformed
        
txtCodigo.setText("");
txtDescripcion.setText("");
txtDestinatario.setText("");
txtDireccion.setText("");
txtDniCamionero.setText("");

txtCodigo.requestFocus();

    }//GEN-LAST:event_btnLimpiarActionPerformed

